import type { KickBadge, KickChatMessage, KickUserIdentity } from "@/types/kick";

/**
 * Timestamped chat dataset for the replay engine (T4).
 * Messages are keyed to the stream clock via `offset_seconds`; the replay
 * engine reveals each message when the clock passes its offset.
 *
 * The full dataset (70k real messages captured from the same stream as the
 * T3 video, plus injected KickBot gift lines) lives in
 * `public/chat-replay.json`, generated by `scripts/build-chat-replay.mjs`
 * and gitignored like the VOD. loadChatReplay() fetches it once and enriches
 * each row with a deterministic Kick-style identity — the capture carries no
 * colors/badges. If the file hasn't been generated, the seeded messages
 * below are tiled across the stream so chat still flows.
 */

const STREAM_START = Date.parse("2026-08-01T12:00:00Z");

/** Build an ISO timestamp `offset` seconds after the mock stream start. */
function at(offset: number): string {
  return new Date(STREAM_START + offset * 1000).toISOString();
}

