/** Row shape in `public/chat-replay.json`. */
export type ChatReplayRow = [offsetSeconds: number, username: string, content: string];

/** Kick-style username palette — vivid, readable on the dark theme. */
const USERNAME_COLORS = [
  "#ff75c8",
  "#e9c46a",
  "#31c4f3",
  "#f3d02f",
  "#a970ff",
  "#4ade80",
  "#f97316",
  "#38bdf8",
  "#fb7185",
  "#c084fc",
  "#34d399",
  "#facc15",
  "#f472b6",
  "#60a5fa",
  "#fb923c",
  "#2dd4bf",
];

/** FNV-1a — stable, so a username keeps its color/badges everywhere. */
function hashUsername(name: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < name.length; i++) {
    h ^= name.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h;
}

const identityCache = new Map<string, KickUserIdentity>();

/**
 * Deterministic Kick-style identity for a captured username (the capture has
 * no colors/badges): everyone gets a palette color; roughly a third are
 * subscribers, some also gift subs, a handful are mods.
 */
export function identityFor(username: string): KickUserIdentity {
  const cached = identityCache.get(username);
  if (cached) return cached;

  let identity: KickUserIdentity;
  if (username === "KickBot") {
    identity = {
      username_color: "#53fc18",
      badges: [{ type: "bot", text: "Bot" }],
    };
  } else {
    const h = hashUsername(username);
    const badges: KickBadge[] = [];
    if ((h >>> 20) % 100 < 2) {
      badges.push({ type: "moderator", text: "Moderator" });
    }
    if ((h >>> 4) % 100 < 35) {
      badges.push({
        type: "subscriber",
        text: "Subscriber",
        count: 1 + ((h >>> 8) % 36),
      });
    }
    if ((h >>> 12) % 100 < 8) {
      badges.push({
        type: "sub_gifter",
        text: "Sub Gifter",
        count: [1, 5, 10, 25, 50, 100, 200][(h >>> 16) % 7],
      });
    }
    identity = {
      username_color: USERNAME_COLORS[h % USERNAME_COLORS.length],
      badges,
    };
  }
  identityCache.set(username, identity);
  return identity;
}

function toMessage(
  [offset, username, content]: ChatReplayRow,
  index: number,
): KickChatMessage {
  return {
    message_id: `replay-${index}`,
    username,
    content,
    timestamp: at(offset),
    offset_seconds: offset,
    identity: identityFor(username),
  };
}

/** Enrich raw replay rows into full chat messages — shared by the client
 * loader below and the server-side loader in `src/lib/server/chat-replay.ts`. */
export function replayRowsToMessages(rows: ChatReplayRow[]): KickChatMessage[] {
  return rows.map(toMessage);
}

/** ≈ the VOD length; the fallback dataset covers the same span. */
const FALLBACK_SPAN_SECONDS = 6 * 3600 + 21 * 60;
const FALLBACK_TILE_SECONDS = 110;

/** Tile the seeded messages across the stream so chat flows without the
 * generated dataset (fresh clone without `assets/`). */
export function tiledSeedFallback(): KickChatMessage[] {
  const out: KickChatMessage[] = [];
  for (let tile = 0; tile * FALLBACK_TILE_SECONDS < FALLBACK_SPAN_SECONDS; tile++) {
    for (const message of mockChatMessages) {
      const offset =
        tile * FALLBACK_TILE_SECONDS + (message.offset_seconds ?? 0);
      out.push({
        ...message,
        message_id: `${message.message_id}-t${tile}`,
        timestamp: at(offset),
        offset_seconds: offset,
      });
    }
  }
  return out;
}

let replayPromise: Promise<KickChatMessage[]> | null = null;

/**
 * The full replay dataset, sorted by offset_seconds. Fetched and enriched
 * once per page — the viewer and creator ChatPanels share the same promise.
 */
export function loadChatReplay(): Promise<KickChatMessage[]> {
  replayPromise ??= fetch("/chat-replay.json")
    .then((res) => {
      if (!res.ok) throw new Error(`chat-replay.json: HTTP ${res.status}`);
      return res.json() as Promise<ChatReplayRow[]>;
    })
    .then((rows) => replayRowsToMessages(rows))
    .catch((error: unknown) => {
      console.warn(
        "Chat replay dataset missing — using the looped seed fallback.",
        "Regenerate it with: node scripts/build-chat-replay.mjs",
        error,
      );
      return tiledSeedFallback();
    });
  return replayPromise;
}
